import{_ as e,o as a,c as i,ag as t}from"./chunks/framework.BZohXCq9.js";const k=JSON.parse('{"title":"RTC、PTP、NTP 与 ROS TimeSync：板端到底是谁在校时","description":"从启动授时、系统时钟驯服到消息时间映射，分清板端多层时间角色","frontmatter":{"title":"RTC、PTP、NTP 与 ROS TimeSync：板端到底是谁在校时","description":"从启动授时、系统时钟驯服到消息时间映射，分清板端多层时间角色","tags":["RTC","PTP","NTP","Linux","TimeSync"],"date":"2026/07/15"},"headers":[],"relativePath":"linux/rtc-ptp-time-source.md","filePath":"linux/rtc-ptp-time-source.md","lastUpdated":1784519165000}'),n={name:"linux/rtc-ptp-time-source.md"};function c(p,s,l,o,d,r){return a(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="rtc、ptp、ntp-与-ros-timesync-板端到底是谁在校时" tabindex="-1">RTC、PTP、NTP 与 ROS TimeSync：板端到底是谁在校时 <a class="header-anchor" href="#rtc、ptp、ntp-与-ros-timesync-板端到底是谁在校时" aria-label="Permalink to &quot;RTC、PTP、NTP 与 ROS TimeSync：板端到底是谁在校时&quot;">​</a></h1><p>嵌入式板上经常同时存在 RTC、<code>ptp4l</code>、<code>phc2sys</code>、<code>timedatectl</code> 和业务自己的 timesync 节点。看到 <code>NTPSynchronized=yes</code> 后，很容易误以为 NTP 正在运行，或者担心 NTP 与 PTP 同时修改系统时间。</p><p>正确做法是先区分每一层的职责。</p><h2 id="四种角色" tabindex="-1">四种角色 <a class="header-anchor" href="#四种角色" aria-label="Permalink to &quot;四种角色&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RTC ──开机时提供初始 wall clock──&gt; CLOCK_REALTIME</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PTP Grandmaster ─&gt; ptp4l ─&gt; PHC</span></span>
<span class="line"><span>                            │</span></span>
<span class="line"><span>                            └─ phc2sys ─&gt; CLOCK_REALTIME</span></span>
<span class="line"><span></span></span>
<span class="line"><span>NTP client ─────────────────────────────&gt; CLOCK_REALTIME</span></span>
<span class="line"><span></span></span>
<span class="line"><span>业务 TimeSync ──映射 PX4 / 传感器时间──&gt; ROS message stamp</span></span></code></pre></div><ul><li><strong>RTC</strong>：断电后保持粗略时间，开机时可通过 <code>hctosys</code> 初始化系统时钟；</li><li><strong>PTP</strong>：通过网卡硬件时钟 PHC 获得高精度网络时间，再由 <code>phc2sys</code> 驯服系统时钟；</li><li><strong>NTP</strong>：另一种网络授时方式，是否在运行要看真实进程和 unit；</li><li><strong>业务 TimeSync</strong>：把 PX4 boot time、PPS 或传感器 timestamp 映射到系统/ROS 时间，不一定修改 <code>CLOCK_REALTIME</code>。</li></ul><h2 id="ntpsynchronized-yes-不是进程清单" tabindex="-1"><code>NTPSynchronized=yes</code> 不是进程清单 <a class="header-anchor" href="#ntpsynchronized-yes-不是进程清单" aria-label="Permalink to &quot;\`NTPSynchronized=yes\` 不是进程清单&quot;">​</a></h2><p><code>timedatectl</code> 的这个字段更接近“系统时钟被标记为已同步”，不能单凭它判断当前时间源一定是 NTP。</p><p>判断真实链路应检查：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --type=service</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --state=running</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -E</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;ptp|timesync|chrony|ntp&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ps</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ef</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -E</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;ptp4l|phc2sys|chronyd|ntpd|systemd-timesyncd&#39;</span></span></code></pre></div><p>如果只有 <code>ptp4l</code> 与 <code>phc2sys</code> 在工作，就不存在 NTP/PTP 双主竞争，即使 <code>timedatectl</code> 显示 synchronized。</p><h2 id="hwclock-失败不等于-rtc-坏了" tabindex="-1"><code>hwclock</code> 失败不等于 RTC 坏了 <a class="header-anchor" href="#hwclock-失败不等于-rtc-坏了" aria-label="Permalink to &quot;\`hwclock\` 失败不等于 RTC 坏了&quot;">​</a></h2><p>普通用户运行 <code>hwclock --show</code> 可能因为设备权限失败。判断 RTC 是否工作，应组合证据：</p><ul><li><code>/sys/class/rtc/rtc0/name</code> 与 <code>since_epoch</code>；</li><li><code>/dev/rtc0</code> 是否存在；</li><li><code>dmesg</code> 是否记录 RTC driver 与 <code>hctosys</code>；</li><li>间隔几秒两次读取 <code>since_epoch</code> 是否递增；</li><li>root 权限下的 <code>hwclock</code>；</li><li>真正需要验证保持能力时，再做 reboot 或断电测试。</li></ul><p>两次计数递增只能证明 RTC 在走时，不能证明电池、断电保持和长期漂移都正常。</p><h2 id="如何找出谁在修改系统时间" tabindex="-1">如何找出谁在修改系统时间 <a class="header-anchor" href="#如何找出谁在修改系统时间" aria-label="Permalink to &quot;如何找出谁在修改系统时间&quot;">​</a></h2><p>建议按顺序检查：</p><ol><li><code>timedatectl</code> 只作为状态入口；</li><li>查实际运行的 time-sync services；</li><li>查 <code>ptp4l</code> 的 port state 与 grandmaster；</li><li>查 <code>phc2sys</code> 的 source/target；</li><li>确认 NTP/chrony 是否同时运行；</li><li>区分业务 timesync 是改系统时钟，还是只改消息 timestamp。</li></ol><h2 id="设计原则" tabindex="-1">设计原则 <a class="header-anchor" href="#设计原则" aria-label="Permalink to &quot;设计原则&quot;">​</a></h2><p>生产系统应只有一条明确的 <code>CLOCK_REALTIME</code> 驯服主链。RTC 负责 bootstrapping，PTP 或 NTP 负责持续校准，业务 TimeSync 负责跨时钟域消息映射。把三者分层，才能避免“服务都 active，但没人知道谁是时间真相”的状态。</p>`,20)])])}const T=e(n,[["render",c]]);export{k as __pageData,T as default};
